import {
  DataGridPremium,
  GridColDef,
  GridRowsProp,
  DataGridPremiumProps,
  GridGroupingColDefOverride,
  isAutogeneratedRow,
} from '@mui/x-data-grid-premium';

interface File {
  hierarchy: string[];
  size?: number;
  updatedAt: string;
}

const rows: GridRowsProp<File> = [
  {
    hierarchy: ['.gitignore'],
    updatedAt: '2022-04-08T07:29:49.228Z',
  },
  {
    hierarchy: ['README.md'],
    size: 1671,
    updatedAt: '2022-04-11T08:05:44.590Z',
  },
  {
    hierarchy: ['next-env.d.ts'],
