        control={
          <Checkbox
            checked={includePinnedRows}
            onChange={(ev) => setIncludePinnedRows(ev.target.checked)}
          />
        }
        label="Aggregate pinned rows"
      />
      <div style={{ height: 400 }}>
        <DataGridPremium
          rows={rows}
          columns={COLUMNS}
          initialState={initialState}
          pinnedRows={{
            top: topRows,
            bottom: bottomRows,
          }}
          aggregationFunctions={
            includePinnedRows
              ? aggregationFunctionsWithPinnedRows
              : GRID_AGGREGATION_FUNCTIONS
          }
        />
      </div>
    </div>
  );
}

function AggregationPinnedRows() {
  const data = useMovieData();
  const [includePinnedRows, setIncludePinnedRows] = React.useState(true);

  const initialState = React.useMemo(() => {
    return {
      aggregation: {
        model: {
          gross: 'sum',
        },
      },
    };
  }, []);

  const { rows, topRows, bottomRows } = React.useMemo(() => {
    const nonPinnedRows = [...data.rows];
    return {
      topRows: [nonPinnedRows.shift()],
      rows: nonPinnedRows,
      bottomRows: [nonPinnedRows.pop()],
    };
  }, [data.rows]);

  return (
    <div style={{ width: '100%' }}>
      <FormControlLabel
        sx={{ ml: 0 }}
        control={
          <Checkbox
            checked={includePinnedRows}
            onChange={(ev) => setIncludePinnedRows(ev.target.checked)}
          />
        }
        label="Aggregate pinned rows"
      />
      <div style={{ height: 400 }}>
        <DataGridPremium
          rows={rows}
          columns={COLUMNS}
          initialState={initialState}
          pinnedRows={{
            top: topRows,
            bottom: bottomRows,
          }}
          aggregationFunctions={
            includePinnedRows
              ? aggregationFunctionsWithPinnedRows
              : GRID_AGGREGATION_FUNCTIONS
          }
        />
      </div>
    </div>
  );
}

